// Packed image capture, validation and lookup.
//
// The image format is the one described in PROTOCOL.md: eleven stages of
// 128 bit cells holding half (TYPE1/TYPE4) or full (TYPE2/TYPE3/TYPE5) node
// records, an NI pattern dictionary, one NI value vector, and explicit front
// locators for the depth-16 and depth-64 forests.
#include "image.hpp"
#include "addrbits.hpp"
#include "fib.hpp"

#include <algorithm>
#include <cstring>
#include <map>
#include <vector>

// ---------------------------------------------------------------- hex words

std::string image_word_hex(const std::bitset<256>& bits) {
    std::string out(64, '0');
    for (int i = 0; i < 64; ++i) {
        unsigned v = 0;
        for (int b = 0; b < 4; ++b) v |= bits[4 * i + b] ? 1u << b : 0;
        out[63 - i] = "0123456789abcdef"[v];
    }
    return out;
}

std::bitset<256> image_word_from_hex(const std::string& text) {
    if (text.size() != 64) throw std::runtime_error("word length");
    std::bitset<256> out;
    for (int i = 0; i < 64; ++i) {
        char c = text[63 - i];
        unsigned v = (c <= '9') ? c - '0' : c - 'a' + 10;
        if (v > 15) throw std::runtime_error("word hex");
        for (int b = 0; b < 4; ++b) out[4 * i + b] = (v >> b) & 1;
    }
    return out;
}

