inline int owner_index(int origin) { return origin == 0 ? 0 : (origin == 16 ? 1 : 2); }
inline int owner_max(int origin) { return origin == 0 ? 16 : (origin == 16 ? 64 : 128); }

inline uint64_t rec_bits(const std::bitset<256>& w, int off, int n) {
    uint64_t v = 0;
    for (int i = 0; i < n; ++i) if (w[off + i]) v |= 1ull << i;
    return v;
}

inline void rec_set(std::bitset<256>& w, int off, int n, uint64_t v) {
    for (int i = 0; i < n; ++i) w[off + i] = ((v >> i) & 1ull) != 0;
}

